const toolGrantEntries = `-- name: ToolGrantEntries :many
SELECT g.payload AS grant_payload,p.payload AS publication_payload
FROM tool_grants g JOIN tool_publications p ON p.account_id=g.account_id AND p.id=g.version
WHERE g.account_id=$1 AND g.key_id=$2 AND g.revoked_at IS NULL AND g.expires_at>now() AND p.status='completed'
ORDER BY g.version,g.id
`

type ToolGrantEntriesParams struct {
	AccountID pgtype.UUID
	KeyID     pgtype.UUID
}

type ToolGrantEntriesRow struct {
	GrantPayload       []byte
	PublicationPayload []byte
}

func (q *Queries) ToolGrantEntries(ctx context.Context, db DBTX, arg ToolGrantEntriesParams) ([]ToolGrantEntriesRow, error) {
	rows, err := db.Query(ctx, toolGrantEntries, arg.AccountID, arg.KeyID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ToolGrantEntriesRow{}
	for rows.Next() {
		var i ToolGrantEntriesRow
		if err := rows.Scan(&i.GrantPayload, &i.PublicationPayload); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

